function addPortrait(){const select=$id('arabic-reciter');if(!select||select.parentElement?.classList.contains('reciter-with-photo'))return false;const label=select.parentElement,wrap=document.createElement('span'),img=document.createElement('img');wrap.className='reciter-with-photo';img.className='reciter-photo';img.alt='Seçili kârî';select.before(wrap);wrap.append(img,select);const paint=()=>{img.src=portraits[select.value]||portraits['ar.alafasy'];img.alt=`${select.options[select.selectedIndex]?.text||'Kârî'} profil fotoğrafı`};select.addEventListener('change',paint);paint();return true}addPortrait()||setTimeout(addPortrait,700);
const drawer=document.querySelector('.app-drawer'),nav=drawer?.querySelector('.drawer-nav');if(drawer&&nav){let box=$id('drawer-apk-download');if(!box){box=document.createElement('section');box.id='drawer-apk-download';box.className='drawer-apk-download';box.innerHTML='<div><span class="eyebrow">ANDROID UYGULAMASI</span><h2>Telefona indir</h2><a class="download-button" href="/downloads/kuran-okuma.apk" download="islam-rehberi.apk">APK indir</a></div><a href="/downloads/kuran-okuma.apk" aria-label="APK indir"><img src="/downloads/kuran-okuma-qr.png" alt="APK indirme QR kodu" width="92" height="92"></a>';nav.insertAdjacentElement('afterend',box)}document.querySelectorAll('.drawer-download').forEach(x=>x.remove())}
